import{_ as t,o as r,c as n,ag as s}from"./chunks/framework.KxDd3USm.js";const _=JSON.parse('{"title":"06.4 CIDR 与路由聚合 ★★","description":"","frontmatter":{},"headers":[],"relativePath":"06-计算机网络/04-CIDR与路由聚合.md","filePath":"06-计算机网络/04-CIDR与路由聚合.md"}'),e={name:"06-计算机网络/04-CIDR与路由聚合.md"};function g(l,o,a,i,d,c){return r(),n("div",null,[...o[0]||(o[0]=[s('<h1 id="_06-4-cidr-与路由聚合-★★" tabindex="-1">06.4 CIDR 与路由聚合 ★★ <a class="header-anchor" href="#_06-4-cidr-与路由聚合-★★" aria-label="Permalink to &quot;06.4 CIDR 与路由聚合 ★★&quot;">​</a></h1><h3 id="为什么要聚合" tabindex="-1">为什么要聚合 <a class="header-anchor" href="#为什么要聚合" aria-label="Permalink to &quot;为什么要聚合&quot;">​</a></h3><p>路由器靠路由表决定往哪转发。互联网上的网段成千上万，如果每个小网段都占路由表一行，路由表会爆炸。<strong>路由聚合（构成超网）<strong>把</strong>多个连续的网段合并成一个更大的前缀</strong>对外通告——道理和子网划分相反：划分子网是&quot;网络位变长&quot;，聚合是&quot;网络位<strong>变短</strong>&quot;。</p><h3 id="聚合方法-找共同前缀" tabindex="-1">聚合方法：找共同前缀 <a class="header-anchor" href="#聚合方法-找共同前缀" aria-label="Permalink to &quot;聚合方法：找共同前缀&quot;">​</a></h3><p>把各网段的地址写成二进制，<strong>从左往右数，数到第一个不同的位为止</strong>，前面相同的位数就是聚合后的前缀长度；聚合地址 = 共同前缀 + 其余位补 0。</p><p><strong>例 1（对齐的 4 个 /24）</strong>：合并 192.168.0.0/24、192.168.1.0/24、192.168.2.0/24、192.168.3.0/24。</p><ul><li>第三字节分别是 0、1、2、3 → 二进制 <code>00000000</code>、<code>00000001</code>、<code>00000010</code>、<code>00000011</code>——前 6 位相同（<code>000000</code>），后 2 位千变万化。</li><li>所以聚合前缀 = 24 − 2 = <strong>/22</strong>，聚合地址 <strong>192.168.0.0/22</strong>，覆盖范围 192.168.0.0 ～ 192.168.3.255（共 4 × 256 = 1024 个地址）。</li><li>验证：/22 的掩码第三字节是 252，块大小 256−252=4，第三字节按 0、4、8、… 分块，0～3 恰好是一个完整块 ✓。</li></ul><p><strong>例 2（对齐的 2 个 /24）</strong>：合并 200.100.16.0/24 与 200.100.17.0/24。</p><ul><li>第三字节 16=<code>00010000</code>、17=<code>00010001</code>，只有最后 1 位不同 → 聚合为 <strong>200.100.16.0/23</strong>（覆盖 16.0 ～ 17.255）。</li><li>验证：/23 块大小 2（掩码第三字节 254），边界 16、18、20……，16～17 是一个完整块 ✓。</li></ul><p><strong>反例演示（边界不对齐——聚合最经典的坑）</strong>：合并 192.168.1.0/24 与 192.168.2.0/24，能写成 192.168.0.0/23 吗？</p><ul><li><strong>第一步，算共同前缀</strong>：第三字节 1 = <code>00000001</code>、2 = <code>00000010</code>，从左往右数，<strong>第 7、8 位不同</strong>，前 6 位一样 → 共同前缀 = 24 − 2 = <strong>/22</strong>，共同部分的地址是 192.168.0.0。</li><li><strong>第二步，过两关</strong>： <ul><li><strong>关一，数量要够</strong>：2 个 /24 只能聚成 <strong>/23</strong>（2^(24−23) = 2）；若要聚成 /22，就要求&quot;2 个网段占满 4 个 /24 的位置&quot;，那多出来的两个位置必须真实存在。</li><li><strong>关二，起点要块对齐</strong>：/22 的块大小是 4，起点必须是 4 的倍数（0、4、8…），而这里的起点是 <strong>1</strong>，不对齐。</li></ul></li><li><strong>所以两关都过不了</strong>：写成 /23（192.168.0.0/23）覆盖 0.0～1.255，<strong>根本没有包含 2.0 网段</strong>；写成 /22（192.168.0.0/22）虽然盖住了 1.0 和 2.0，却<strong>顺带&quot;吞&quot;了并不存在的 0.0 和 3.0</strong>——这叫过度概括，不是聚合。</li><li><strong>正确做法是换配对</strong>：192.168.<strong>2</strong>.0/24 与 192.168.<strong>3</strong>.0/24 —— 起点 2 是偶数（对齐 ✓）、数量 2 个（够 ✓）→ 合成 <strong>192.168.2.0/23</strong>，覆盖 2.0～3.255，干净。</li><li>教训：<strong>聚合 = 共同前缀 + 块对齐，两个条件缺一不可</strong>——n 个连续 /24 聚合，起始网络号的对应字节必须是块大小的整数倍（2 个从偶数起、4 个从 4 的倍数起、8 个从 8 的倍数起），且必须&quot;凑满&quot;完整的块。</li></ul><p><strong>快速判定口诀</strong>：k 个 /24 网段能否聚成一个 /x —— ① 数量 k = 2^(24−x)（2 个 → /23，4 个 → /22，8 个 → /21）；② 起始网段的地址落在以块大小为步长的边界上。</p><p><strong>应试动作</strong>：① 聚合 = 找共同前缀，考场直接把关键字节转二进制数位数（连续 2 的幂个网段才可精确聚合）；② 看到选项先查两件事：<strong>前缀长度对不对（数量够不够）</strong>、<strong>起始边界对不对（对齐没有）</strong>，两关都过才是正确答案；③ 反过来也常考：给出一个 /22，问它覆盖哪些 /24——按块大小 4 列边界即可。</p>',13)])])}const p=t(e,[["render",g]]);export{_ as __pageData,p as default};
